<?php
function total(mysqli $db,string $table):int{return (int)$db->query("SELECT COUNT(*) FROM `$table`")->fetch_row()[0];}
$stats=[['Total Barang',total($koneksi,'barang'),'▤'],['Kategori',total($koneksi,'kategori'),'◫'],['Penyuplai',total($koneksi,'penyuplai'),'♧'],['Barang Masuk',total($koneksi,'barangmasuk'),'↙']];
$recent=$koneksi->query('SELECT bm.tanggalmasuk,bm.jumlah,bm.keterangan,b.namabarang,u.namauser FROM barangmasuk bm LEFT JOIN barang b ON bm.idbarang=b.idbarang LEFT JOIN user u ON bm.iduser=u.iduser ORDER BY bm.idbarangmasuk DESC LIMIT 6');
$low=$koneksi->query('SELECT kodebarang,namabarang,stok,satuan FROM barang ORDER BY stok ASC LIMIT 5');
?><div class="page-heading"><div><h1>Dashboard</h1><p>Ringkasan inventaris dan aktivitas terbaru.</p></div><a class="btn primary" href="index.php?page=barangmasuk&new=1">＋ Catat Barang Masuk</a></div><div class="stat-grid"><?php foreach($stats as $s):?><article class="stat-card"><div><?=e($s[0])?><span class="stat-icon"><?=e($s[2])?></span></div><strong><?=number_format($s[1])?></strong><small>Data terdaftar</small></article><?php endforeach?></div><section class="panel"><div class="panel-heading"><div><h2>Aktivitas Barang Masuk</h2><p>Catatan terbaru inventaris</p></div><a class="btn secondary" href="index.php?page=barangmasuk">Lihat semua →</a></div><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Tanggal</th><th>Jumlah</th><th>Petugas</th><th>Keterangan</th></tr></thead><tbody><?php if($recent->num_rows):while($r=$recent->fetch_assoc()):?><tr><td><?=e($r['namabarang']??'-')?></td><td><?=e($r['tanggalmasuk'])?></td><td><span class="badge-pink">+<?=e($r['jumlah'])?></span></td><td><?=e($r['namauser']??'-')?></td><td><?=e($r['keterangan'])?></td></tr><?php endwhile;else:?><tr><td colspan="5" class="empty">Belum ada data barang masuk.</td></tr><?php endif?></tbody></table></div></section><section class="panel"><div class="panel-heading"><div><h2>Stok Perlu Diperhatikan</h2><p>Barang dengan stok terendah</p></div><a class="btn secondary" href="index.php?page=barang">Kelola barang →</a></div><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama Barang</th><th>Stok</th><th>Status</th></tr></thead><tbody><?php if($low->num_rows):while($r=$low->fetch_assoc()):?><tr><td><?=e($r['kodebarang'])?></td><td><?=e($r['namabarang'])?></td><td><?=e($r['stok'].' '.$r['satuan'])?></td><td><span class="<?=((int)$r['stok']<=5?'badge-warning':'badge-pink')?>"><?=((int)$r['stok']<=5?'Stok rendah':'Tersedia')?></span></td></tr><?php endwhile;else:?><tr><td colspan="4" class="empty">Belum ada data barang.</td></tr><?php endif?></tbody></table></div></section>
